package com.example.commerce.order.orders;
import java.util.Map;import org.springframework.amqp.core.*;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Configuration class OrderEventConfiguration{@Bean TopicExchange orderExchange(){return new TopicExchange("commerce.orders");}@Bean Queue orderAuditQueue(){return QueueBuilder.durable("commerce.orders.audit").build();}@Bean Binding orderBinding(Queue orderAuditQueue,TopicExchange orderExchange){return BindingBuilder.bind(orderAuditQueue).to(orderExchange).with("order.#");}}
@Component public class OrderEventPublisher{private final NamedParameterJdbcTemplate jdbc;private final RabbitTemplate rabbit;public OrderEventPublisher(NamedParameterJdbcTemplate jdbc,RabbitTemplate rabbit){this.jdbc=jdbc;this.rabbit=rabbit;}
 @Scheduled(fixedDelay=1000) public void publish(){var rows=jdbc.queryForList("SELECT id,event_type,payload FROM order_event_outbox WHERE published_at IS NULL ORDER BY id LIMIT 50",Map.of());for(var row:rows){long id=((Number)row.get("id")).longValue();String type=(String)row.get("event_type");Object value=row.get("payload");String payload=value instanceof byte[] bytes?new String(bytes,java.nio.charset.StandardCharsets.UTF_8):value.toString();rabbit.convertAndSend("commerce.orders","order."+type.toLowerCase(),payload);jdbc.update("UPDATE order_event_outbox SET published_at=CURRENT_TIMESTAMP WHERE id=:id AND published_at IS NULL",Map.of("id",id));}}}
